var health = 100
var max_health = 100

func take_damage(amount):
	health -= amount
	if health < 0:
		health = 0

func heal(amount):
	health += amount
	if health > max_health:
		health = max_health

func report():
	if health > 0:
		print("Alive")
	else:
		print("Down")
